import {mapGetters} from 'vuex'
import HiddenDetial from "./hiddenDetial";
import {hiddenList, hiddenDelete, securityDelete} from "@/api/safeDanger/hiddenCategory"
import {getDictList, getDictCmdbList} from "@/api/dict";
// import {getHiddenPCDict} from "@/utils/hiddenDict";

export default {
  name: "hiddenTable",
  components: {HiddenDetial},
  props: {
    category: {
      type: String,
      default: null
    },
    roomId: {
      type: Number,
    },
    isEdit: {
      type: Boolean,
      default: false
    },
    fromType: {
      type: String,
      default: null
    },
    yhbz: {
      type: String,
      default: null
    },
  },
  data() {
    return {
      detailObj: {},
      // options: getHiddenPCDict,
      options: [],
      tableList: [],
      loading: false,
      tableHeight: undefined,
      // 查询参数
      queryParams: {
        categoryId: '',
        type: '',
      },
      multipleSelection: [],


      hiddenDialogVisible: false,
      hiddenDialogTitle: '',
      hiddenType: false,
    }
  },
  created() {
    this.getList();
  },
  mounted() {
    this.getDictList('hidden_category_standard')
  },
  methods: {
    getDictList(code) {
      //加载字典
      getDictList(code).then(res => {
        if (code === 'hidden_category_standard') {
          // this.swStateList = res.data;
          this.options = res.data
        }
      });
    },
    handleQuery() {
      this.getList();
    },
    resetQuery() {
      this.resetForm("queryForm")
      this.handleQuery()
    },
    handleAdd() {
      this.hiddenDialogTitle = '新增'
      this.hiddenDialogVisible = true
      this.hiddenType = 'add';
    },

    formatRectificationStatus(row) {
      if (row.rectificationStatus == 1) {
        return '已整改'
      } else {
        return '未整改'
      }
    },
    closeDialog() {
      this.hiddenDialogVisible = false
      this.getList();
    },
    getList() {
      this.queryParams.categoryId = this.roomId
      this.loading = true

      if(this.fromType == 'yhtb'){
        //来自隐患提报
        this.queryParams.type = this.yhbz;
      }

      hiddenList(this.queryParams).then(response => {
        this.tableList = response.data.records
      }).finally(() => {
        this.loading = false
      })
    },
    handleSelectionChange(val) {
      this.ids = []
      this.multipleSelection = val;
    },
    btnClick(row){
      this.$emit('select',row);
    },
    handleUpdate() {
      this.hiddenDialogTitle = '修改'
      this.detailObj = this.multipleSelection[0]
      this.hiddenDialogVisible = true
      this.hiddenType = 'edit'
    },
    handleDel() {
      this.$confirm('是否确认删除选中数据项?', "警告", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(() => {
        hiddenDelete(this.multipleSelection.map(item => {
          return item.id;
        })).then(res => {
          this.$message.success(res.msg)
          this.getList()
        })
      })
    },

    handleClose() {
      this.hiddenDialogVisible = false
      this.getList();
    },
  }
}
